/* ── Real-time polling notifications ─────────────────────────────────────── */
function useOrderNotifications(onNewOrder) {
  const lastPollRef = React.useRef(null);
  useEffect(() => {
    const token = localStorage.getItem('nb_admin_token');
    if (!token) return;
    const authH = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` };
    const poll = async () => {
      try {
        const params = lastPollRef.current ? `?since=${encodeURIComponent(lastPollRef.current)}` : '';
        const res    = await fetch(`/api/admin/notifications/pending${params}`, { headers: authH });
        if (res.status === 401) {
            // Session expired — redirect to login (interval clears on unmount)
            window.location.href = '/admin';
            return;
        }
        if (!res.ok) return;
        const data = await res.json();
        if (data.alerts && data.alerts.length > 0) {
          lastPollRef.current = new Date().toISOString();
          data.alerts.forEach(alert => onNewOrder(alert));
          try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            [660, 880, 1100].forEach((freq, i) => {
              const osc  = ctx.createOscillator();
              const gain = ctx.createGain();
              osc.connect(gain); gain.connect(ctx.destination);
              osc.frequency.value = freq; osc.type = 'sine';
              gain.gain.setValueAtTime(0.25, ctx.currentTime + i * 0.18);
              gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.18 + 0.15);
              osc.start(ctx.currentTime + i * 0.18);
              osc.stop(ctx.currentTime + i * 0.18 + 0.15);
            });
          } catch(_) {}
        }
      } catch(_) {}
    };
    poll();
    const iv = setInterval(poll, 5000);
    return () => clearInterval(iv);
  }, [onNewOrder]);
}

/* ── Alert Banner ─────────────────────────────────────────────────────────── */
