/* ── Terminal Config Block (2026-07-25) ──────────────────────────────────────
   One block per terminal: master on/off checkbox, then exchange checkboxes
   and segment-type checkboxes that stay disabled until the terminal is
   ticked on. Amber left border while there are unsaved edits, green once
   saved and on. Matches the terminal-first mockup the client approved. */
function TerminalConfigBlock({ term, draft, dirty, saving, statusLabel, onToggleTerminal, onToggleExchange, onToggleSegment, onToggleAll, onSave, onReset, T }) {
  const showMcxNote = draft.exchanges.includes('MCX') && draft.segments.includes('CM');
  const borderColor = dirty ? T.warn : (draft.on ? '#22c55e' : T.bdr);
  const pillBg  = dirty ? T.warnBg : (draft.on ? T.okBg : T.surf2);
  const pillCol = dirty ? T.warnTx : (draft.on ? T.ok    : T.tx3);
  return (
    <div style={{ background:T.surf, border:`0.5px solid ${T.bdr}`, borderLeft:`3px solid ${borderColor}`, borderRadius:12, padding:'16px 20px', marginBottom:14, transition:'border-left-color .25s' }}>
      <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:14 }}>
        <label style={{ display:'flex', alignItems:'center', gap:8, fontSize:15, fontWeight:600, color:T.tx, cursor:'pointer' }}>
          <input type="checkbox" checked={draft.on} onChange={e=>onToggleTerminal(term.code, e.target.checked)} style={{ width:17, height:17, cursor:'pointer' }}/>
          {term.label}
        </label>
        <span style={{ fontSize:10.5, fontWeight:600, padding:'2px 9px', borderRadius:20, background:pillBg, color:pillCol }}>{statusLabel}</span>
      </div>
      <div style={{ display:'flex', alignItems:'center', gap:26, marginBottom:12, paddingLeft:2 }}>
        <span style={{ fontSize:10, color:T.tx3, width:58, textTransform:'uppercase', letterSpacing:.4, flexShrink:0 }}>Exchange</span>
        {TERM_EXCHANGES.map(ex => (
          <label key={ex} style={{ display:'flex', alignItems:'center', gap:7, fontSize:13.5, color: draft.on?T.tx:T.tx3, cursor: draft.on?'pointer':'not-allowed' }}>
            <input type="checkbox" disabled={!draft.on} checked={draft.exchanges.includes(ex)} onChange={e=>onToggleExchange(term.code, ex, e.target.checked)} style={{ width:15, height:15, cursor: draft.on?'pointer':'not-allowed' }}/>
            {ex}
          </label>
        ))}
      </div>
      <div style={{ display:'flex', alignItems:'center', gap:26, marginBottom: showMcxNote?4:12, paddingLeft:2 }}>
        <span style={{ fontSize:10, color:T.tx3, width:58, textTransform:'uppercase', letterSpacing:.4, flexShrink:0 }}>Segment</span>
        <label style={{ display:'flex', alignItems:'center', gap:7, fontSize:13.5, color: draft.on?T.tx:T.tx3, cursor: draft.on?'pointer':'not-allowed' }}>
          <input type="checkbox" disabled={!draft.on} checked={draft.segments.includes('CM') && draft.segments.includes('FO')} onChange={e=>onToggleAll(term.code, e.target.checked)} style={{ width:15, height:15, cursor: draft.on?'pointer':'not-allowed' }}/>
          All
        </label>
        {TERM_SEGMENT_TYPES.map(seg => (
          <label key={seg} style={{ display:'flex', alignItems:'center', gap:7, fontSize:13.5, color: draft.on?T.tx:T.tx3, cursor: draft.on?'pointer':'not-allowed' }}>
            <input type="checkbox" disabled={!draft.on} checked={draft.segments.includes(seg)} onChange={e=>onToggleSegment(term.code, seg, e.target.checked)} style={{ width:15, height:15, cursor: draft.on?'pointer':'not-allowed' }}/>
            {seg}
          </label>
        ))}
      </div>
      {showMcxNote && (
        <div style={{ fontSize:10.5, color:T.warnTx, margin:'0 0 10px 62px' }}>MCX only has a Futures &amp; Options segment — CM won't apply there.</div>
      )}
      <div style={{ display:'flex', alignItems:'center', gap:10 }}>
        <button onClick={()=>onSave(term.code)} disabled={!dirty||saving}
          style={{ background: (!dirty||saving)?T.surf2:T.brand, color:(!dirty||saving)?T.tx3:'#fff', border:'none', borderRadius:7, padding:'8px 20px', fontSize:12.5, fontWeight:600, cursor:(!dirty||saving)?'not-allowed':'pointer', fontFamily:"'DM Sans',sans-serif" }}>
          {saving?'Saving...':'Save changes'}
        </button>
        <button onClick={()=>onReset(term.code)} disabled={!dirty||saving}
          style={{ background:'transparent', color:T.tx2, border:`0.5px solid ${T.bdr}`, borderRadius:7, padding:'8px 14px', fontSize:12, cursor:(!dirty||saving)?'not-allowed':'pointer', fontFamily:"'DM Sans',sans-serif", opacity:(!dirty||saving)?.5:1 }}>
          Reset
        </button>
      </div>
    </div>
  );
}

/* ── Segment Control Panel ────────────────────────────────────────────────── */
// Terminal-first redesign (2026-07-25): admins configure each terminal
// (which exchanges + segment types it covers) instead of picking a terminal
// per segment row. A segment's Active/Inactive status and served-by list are
// now purely a read-only view, derived server-side from the saved terminal
// configs -- there is no more manual per-segment Enable/Disable button.
function SegmentControl({ segments, terminalConfigs, onAlert, onSaveTerminal, communicating, savingTerminal, T }) {
  const S = getAdminStyles(T);
  const enabled = segments.filter(s => s.is_enabled).length;

  const emptyDraft = () => ({ on:false, exchanges:[], segments:[] });
  const [draft, setDraft] = useState({});
  const [savedSnap, setSavedSnap] = useState({});
  const [initialized, setInitialized] = useState(false);

  // Seed local editing state from the server once terminalConfigs first
  // arrives. Intentionally only runs once -- after that, draft/savedSnap are
  // only updated via the user's own edits/saves, so an unrelated background
  // refresh (e.g. after Alert Clients) never stomps an in-progress edit.
  useEffect(() => {
    if (initialized || !terminalConfigs || terminalConfigs.length === 0) return;
    const d = {}, s = {};
    TERMINALS.forEach(term => {
      const row = terminalConfigs.find(tc => tc.terminal === term.code);
      const shaped = row
        ? { on: !!row.is_enabled, exchanges: (row.exchanges||'').split(',').map(v=>v.trim()).filter(Boolean), segments: (row.segments||'').split(',').map(v=>v.trim()).filter(Boolean) }
        : emptyDraft();
      d[term.code] = shaped;
      s[term.code] = { on:shaped.on, exchanges:[...shaped.exchanges], segments:[...shaped.segments] };
    });
    setDraft(d);
    setSavedSnap(s);
    setInitialized(true);
  }, [terminalConfigs, initialized]);

  const isDirty = (code) => {
    const a = draft[code], b = savedSnap[code];
    if (!a || !b) return false;
    return a.on !== b.on
      || [...a.exchanges].sort().join(',') !== [...b.exchanges].sort().join(',')
      || [...a.segments].sort().join(',')  !== [...b.segments].sort().join(',');
  };

  const handleToggleTerminal = (code, on) => {
    setDraft(d => ({ ...d, [code]: on ? { ...d[code], on } : { on, exchanges:[], segments:[] } }));
  };
  const handleToggleExchange = (code, ex, checked) => {
    setDraft(d => {
      const cur  = d[code].exchanges;
      const next = checked ? [...new Set([...cur, ex])] : cur.filter(x=>x!==ex);
      return { ...d, [code]: { ...d[code], exchanges: next } };
    });
  };
  const handleToggleSegment = (code, seg, checked) => {
    setDraft(d => {
      const cur  = d[code].segments;
      const next = checked ? [...new Set([...cur, seg])] : cur.filter(x=>x!==seg);
      return { ...d, [code]: { ...d[code], segments: next } };
    });
  };
  const handleToggleAll = (code, checked) => {
    setDraft(d => ({ ...d, [code]: { ...d[code], segments: checked ? ['CM','FO'] : [] } }));
  };
  const handleReset = (code) => {
    const snap = savedSnap[code];
    setDraft(d => ({ ...d, [code]: { on:snap.on, exchanges:[...snap.exchanges], segments:[...snap.segments] } }));
  };
  const handleSave = async (code) => {
    const d = draft[code];
    const ok = await onSaveTerminal(code, d.on, d.exchanges, d.segments);
    if (ok) setSavedSnap(s => ({ ...s, [code]: { on:d.on, exchanges:[...d.exchanges], segments:[...d.segments] } }));
  };

  const orderedSegments = [...segments].sort((a,b) =>
    SEGMENT_ORDER.indexOf(`${a.exchange}-${a.segment}`) - SEGMENT_ORDER.indexOf(`${b.exchange}-${b.segment}`)
  );

  return (
    <div>
      {/* Stat cards */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, marginBottom:20 }}>
        {[
          { label:'Total Segments',  value:segments.length,        color:T.brand },
          { label:'Active',          value:enabled,                color:T.ok    },
          { label:'Inactive',        value:segments.length-enabled, color:T.err  },
        ].map(c => (
          <div key={c.label} style={{ ...S.statCard }}>
            <div style={{ ...S.statLabel }}>{c.label}</div>
            <div style={{ ...S.statNum(c.color) }}>{c.value}</div>
          </div>
        ))}
      </div>

      <div style={{ background:T.brandL, border:`0.5px solid ${T.brand}`, borderRadius:8, padding:'10px 16px', marginBottom:18, fontSize:12, color:T.tx2, lineHeight:1.6 }}>
        Tick a terminal on first — its exchange and segment checkboxes stay disabled until you do. A segment counts as Active once at least one saved terminal covers it.
      </div>

      <div style={{ fontSize:13, fontWeight:600, color:T.tx, margin:'0 0 10px' }}>Configure terminals</div>
      {TERMINALS.map(term => {
        const d = draft[term.code] || emptyDraft();
        const dirty = isDirty(term.code);
        const statusLabel = dirty ? 'Unsaved changes' : (d.on ? `Live · ${d.exchanges.length} exch / ${d.segments.length} seg` : 'Off');
        return (
          <TerminalConfigBlock
            key={term.code}
            term={term}
            draft={d}
            dirty={dirty}
            saving={!!savingTerminal[term.code]}
            statusLabel={statusLabel}
            onToggleTerminal={handleToggleTerminal}
            onToggleExchange={handleToggleExchange}
            onToggleSegment={handleToggleSegment}
            onToggleAll={handleToggleAll}
            onSave={handleSave}
            onReset={handleReset}
            T={T}
          />
        );
      })}

      <div style={{ fontSize:13, fontWeight:600, color:T.tx, margin:'22px 0 10px' }}>Segment status</div>
      <div style={{ ...S.card }}>
        <div style={{ display:'grid', gridTemplateColumns:'2fr 120px 180px 160px', padding:'9px 20px', background:T.surf2, borderBottom:`0.5px solid ${T.bdr}` }}>
          {['Segment','Status','Served By','Actions'].map(h=>(
            <div key={h} style={{ fontSize:10, color:T.tx2, fontWeight:600, textTransform:'uppercase', letterSpacing:.4 }}>{h}</div>
          ))}
        </div>
        {orderedSegments.map((s, i) => {
          const key = `${s.exchange}-${s.segment}`;
          const servedBy = (s.terminals || '').split(',').map(v=>v.trim()).filter(Boolean);
          const ec = EX_COLORS[s.exchange];
          return (
            <div key={key} style={{ display:'grid', gridTemplateColumns:'2fr 120px 180px 160px', padding:'13px 20px', alignItems:'center', borderBottom: i<orderedSegments.length-1?`0.5px solid ${T.bdr}`:'none', background:s.is_enabled?T.brandL:T.surf }}>
              <div>
                <div style={{ fontSize:13, fontWeight:500, color:T.tx }}>{SEGMENT_NAMES[s.segment] || s.segment}</div>
                <div style={{ fontSize:10, color:T.tx3, marginTop:2, display:'flex', alignItems:'center', gap:6 }}>
                  <span style={{ ...S.badge(ec.bg, ec.col, ec.bdr) }}>{s.exchange}</span> {s.segment}
                </div>
              </div>
              <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                <div style={{ width:7, height:7, borderRadius:'50%', background:s.is_enabled?'#16a34a':'#d1d5db' }}/>
                <span style={{ fontSize:12, fontWeight:500, color:s.is_enabled?T.ok:T.tx3 }}>{s.is_enabled?'Active':'Inactive'}</span>
              </div>
              <div style={{ fontSize:12, color:T.tx2 }}>
                {servedBy.length ? servedBy.map(c=>TERMINALS.find(t=>t.code===c)?.label||c).join(', ') : '—'}
              </div>
              <div>
                <button onClick={()=>onAlert(s.exchange,s.segment)} disabled={communicating[key]}
                  style={{ ...S.btnGhost, fontSize:11, padding:'5px 12px', opacity:communicating[key]?.6:1 }}>
                  {communicating[key]?'Sending...':'📢 Alert Clients'}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ══ MAIN AdminDashboard ══════════════════════════════════════════════════════ */
export default function AdminDashboard({ admin, onLogout }) {
  // Dealer Admin and Sub User have no access to Segment Control (the default
  // tab), so both must default to a tab they can actually see -- 'orders'
  // (Sq-Off Orders), the first item in both of their allowed lists. ADMIN
  // behavior is unchanged.
  const [activeNav,     setActiveNav]     = useState(() => (admin.role === 'DEALER_ADMIN' || admin.role === 'SUBUSER') ? 'orders' : 'segments');
  // Segment Control (2026-07-22): every page load/refresh/re-login re-fetches
  // segments from scratch, showing "Loading segments..." for however long
  // that round trip takes (2-3s). To make repeat visits feel instant, cache
  // the last-fetched segments in localStorage and show them immediately on
  // mount, then silently refresh with live data in the background -- the
  // loading text now only appears on a truly first-ever load (no cache yet).
  const SEGMENTS_CACHE_KEY = 'nb_segments_cache_v1';
  const SEGMENTS_CACHE_MAX_AGE_MS = 60 * 60 * 1000; // 1 hour
  const readSegmentsCache = () => {
    try {
      const raw = localStorage.getItem(SEGMENTS_CACHE_KEY);
      if (!raw) return null;
      const { segments: cached, ts } = JSON.parse(raw);
      if (!Array.isArray(cached) || !ts || Date.now() - ts > SEGMENTS_CACHE_MAX_AGE_MS) return null;
      return cached;
    } catch { return null; }
  };
  const [segments,      setSegments]      = useState(() => readSegmentsCache() || []);
  const [loading,       setLoading]       = useState(() => readSegmentsCache() === null);
  const [terminalConfigs, setTerminalConfigs] = useState([]);
  const [savingTerminal,  setSavingTerminal]  = useState({});
  const [communicating, setCommunicating] = useState({});
  const [toast,         setToast]         = useState(null);
  const [orderAlerts,   setOrderAlerts]   = useState([]);
  const [themeKey,      setThemeKey]      = useState(() => localStorage.getItem('nb_admin_theme')||'light');

  const T = ADMIN_THEMES[themeKey];

  // Inject CSS vars + DM Sans whenever theme changes
  useEffect(() => {
    injectAdminThemeVars(T);
    localStorage.setItem('nb_admin_theme', themeKey);
    document.body.style.background = T.bg;
    document.body.style.fontFamily = "'DM Sans',-apple-system,sans-serif";

    // Inject global CSS overrides for sub-pages dark/light theme
    let el = document.getElementById('nb-admin-theme-style');
    if (!el) { el = document.createElement('style'); el.id = 'nb-admin-theme-style'; document.head.appendChild(el); }
    el.textContent = `
      .nb-admin-content, .nb-admin-content * { font-family: 'DM Sans',-apple-system,sans-serif !important; }
      .nb-admin-content { color: ${T.tx} !important; }
      .nb-admin-content > div { background: transparent !important; }
      .nb-admin-content [style*="background: '#fff'"],
      .nb-admin-content [style*='background: "#fff"'] { background: ${T.surf} !important; }
      .nb-admin-content input, .nb-admin-content select {
        background: ${T.surf2} !important;
        color: ${T.tx} !important;
        border-color: ${T.bdr2} !important;
      }
    `;
  }, [T, themeKey]);

  const toggleTheme = () => setThemeKey(k => k==='light'?'dark':'light');

  const showToast = (msg, type='success') => { setToast({msg,type}); setTimeout(()=>setToast(null),4000); };

  const handleNewOrder = useCallback((orderData) => {
    setOrderAlerts(prev => [...prev, orderData]);
  }, []);

  useOrderNotifications(handleNewOrder);

  const handleDismissAlerts = () => {
    const ids = orderAlerts.map(a=>a.orderId);
    setOrderAlerts([]);
    const token = localStorage.getItem('nb_admin_token');
    if (token && ids.length>0) fetch('/api/admin/notifications/seen',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({order_ids:ids})}).catch(()=>{});
  };

  const handleViewOrders = () => { setActiveNav('orders'); handleDismissAlerts(); };

  const loadSegments = async () => {
    try {
      const res = await (await fetch('/api/admin/control/segments',{headers:{'Authorization':`Bearer ${localStorage.getItem('nb_admin_token')}`}})).json();
      const fresh = res.segments || [];
      setSegments(fresh);
      // Cache the fresh result so the next mount (refresh / re-login) can
      // paint instantly from cache instead of showing "Loading segments...".
      try { localStorage.setItem(SEGMENTS_CACHE_KEY, JSON.stringify({ segments: fresh, ts: Date.now() })); } catch {}
    }
    catch { showToast('Failed to load segments.','error'); }
    finally { setLoading(false); }
  };

  // Segment Control (2026-07-25, terminal-first redesign): fetches each
  // terminal's saved on/off + exchanges + segments so the config blocks can
  // be pre-filled with the current live configuration on load.
  const loadTerminalConfigs = async () => {
    try {
      const res = await (await fetch('/api/admin/control/terminals',{headers:{'Authorization':`Bearer ${localStorage.getItem('nb_admin_token')}`}})).json();
      setTerminalConfigs(res.terminals || []);
    } catch { showToast('Failed to load terminal configuration.','error'); }
  };

  useEffect(() => { loadSegments(); loadTerminalConfigs(); }, []);

  // Saves one terminal's configuration, then refreshes both segments and
  // terminal configs from the server response in a single round trip.
  // Returns true/false so the SegmentControl UI only updates its "saved"
  // snapshot on success (keeping unsaved edits visible if the save fails).
  const handleSaveTerminal = async (terminal, enabled, exchanges, segmentsArr) => {
    setSavingTerminal(s => ({ ...s, [terminal]: true }));
    try {
      const res = await (await fetch('/api/admin/control/terminals/save',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('nb_admin_token')}`},body:JSON.stringify({terminal,enabled,exchanges,segments:segmentsArr})})).json();
      if (res.error) { showToast(res.error,'error'); return false; }
      setTerminalConfigs(res.terminals || []);
      setSegments(res.segments || []);
      try { localStorage.setItem(SEGMENTS_CACHE_KEY, JSON.stringify({ segments: res.segments || [], ts: Date.now() })); } catch {}
      showToast(`${terminal} configuration saved`);
      return true;
    } catch (err) { showToast(err.message||'Failed to save terminal.','error'); return false; }
    finally { setSavingTerminal(s => ({ ...s, [terminal]: false })); }
  };

  const handleAlert = async (exchange, segment) => {
    const key = `${exchange}-${segment}`;
    if (!window.confirm(`Send Email + WhatsApp to all clients with open ${exchange} ${segment} positions?`)) return;
    setCommunicating(c=>({...c,[key]:true}));
    try {
      const res = await (await fetch('/api/admin/control/communicate',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('nb_admin_token')}`},body:JSON.stringify({exchange,segment,send_email:true,send_whatsapp:true})})).json();
      showToast(`Sent to ${res.total_clients} clients`);
    } catch(err) { showToast('Communication failed.','error'); }
    finally { setCommunicating(c=>({...c,[key]:false})); }
  };

  const navTitles = {
    segments: { title:'Segment Control',       sub:'Manage exchange segments and client communications' },
    cddsqoff: { title:'CDD Sq.off Report',      sub:'Restrict square-off to a whitelisted set of clients' },
    orders:   { title:'Square-Off Orders',      sub:'View and manage client sq-off requests'            },
    alerts:   { title:'Client Alerts',          sub:'Bulk communication history'                        },
    bfupload: { title:'B/F Position Upload',    sub:'Upload daily NSE FO and MCX carried-forward files' },
    reports:  { title:'Order Reports',          sub:'Download exchange-wise reports'                     },
    dealer:   { title:'Dealer Access',          sub:'SSO and dealer order management'                    },
    logs:     { title:'Audit Logs',             sub:'System activity and admin actions'                  },
    syslogs:  { title:'System Logs',            sub:'Complete audit trail for compliance'                },
    users:    { title:'User Management',        sub:'Admin and sub-user access control'                  },
    clientsearch: { title:'Client Search',      sub:'Search clients by UCC, Mobile, Email, BO ID or PAN' },
    clients:  { title:'Client Upload',          sub:'Bulk upload clients via CSV file'                   },
    syncmon:  { title:'Sync Monitor',           sub:'DropCopy sync status and logs'                      },
  };
  const current = navTitles[activeNav]||navTitles.segments;
  const S = getAdminStyles(T);

  return (
    <AdminThemeContext.Provider value={{ themeKey, T, toggleTheme }}>
      <div style={{ display:'flex', minHeight:'100vh', background:T.bg, fontFamily:"'DM Sans',-apple-system,sans-serif" }}>

        {/* Order alert banner */}
        <OrderAlertBanner alerts={orderAlerts} onDismiss={handleDismissAlerts} onViewOrders={handleViewOrders}/>

        {/* Toast */}
        {toast && <div style={{...S.toast(toast.type)}}>{toast.msg}</div>}

        {/* Sidebar */}
        <Sidebar activeNav={activeNav} onNav={setActiveNav} admin={admin} pendingCount={orderAlerts.length} T={T}
          onLogout={()=>{ localStorage.removeItem('nb_admin_token'); localStorage.removeItem('nb_admin'); onLogout(); }}/>

        {/* Main */}
        <div style={{ marginLeft:210, flex:1, display:'flex', flexDirection:'column', minHeight:'100vh' }}>
          <Topbar title={current.title} subtitle={current.sub} admin={admin} T={T} themeKey={themeKey} toggleTheme={toggleTheme}/>

          <div className="nb-admin-content" style={{ padding:'20px 24px', flex:1, background:T.bg }}>
            {activeNav==='segments' && (
              loading
                ? <div style={{...S.empty}}>Loading segments...</div>
                : <SegmentControl segments={segments} terminalConfigs={terminalConfigs} onAlert={handleAlert} onSaveTerminal={handleSaveTerminal} communicating={communicating} savingTerminal={savingTerminal} T={T}/>
            )}
            {/* Keep components mounted to avoid reload delay on tab switch */}
            <div style={{display: activeNav==='cddsqoff'?'block':'none'}}><CddSqoffReport/></div>
            <div style={{display: activeNav==='orders'  ?'block':'none'}}><SqOffOrders/></div>
            <div style={{display: activeNav==='alerts'  ?'block':'none'}}><ClientAlerts/></div>
            <div style={{display: activeNav==='bfupload'?'block':'none'}}><BFUpload/></div>
            <div style={{display: activeNav==='reports' ?'block':'none'}}><OrderReports/></div>
            <div style={{display: activeNav==='dealer'  ?'block':'none'}}><DealerAccessPanel/></div>
            <div style={{display: activeNav==='logs'    ?'block':'none'}}><AuditLogs/></div>
            <div style={{display: activeNav==='syslogs' ?'block':'none'}}><SystemLogsPanel/></div>
            <div style={{display: activeNav==='syncmon' ?'block':'none'}}><SyncMonitor/></div>
            <div style={{display: activeNav==='users'   ?'block':'none'}}><UserManagement/></div>
            <div style={{display: activeNav==='clientsearch' ?'block':'none'}}><ClientSearch/></div>
            <div style={{display: activeNav==='clients' ?'block':'none'}}><ClientUpload/></div>
          </div>

          <div style={{ textAlign:'center', padding:'12px', fontSize:10, color:T.tx3, borderTop:`0.5px solid ${T.bdr}` }}>
            Navia Markets Ltd · RMS Admin Terminal · {new Date().getFullYear()}
          </div>
        </div>
      </div>
    </AdminThemeContext.Provider>
  );
}